diff --git a/encryption/config.go b/encryption/config.go
new file mode 100644
index 0000000..56a4866
--- /dev/null
+++ b/encryption/config.go
@@ -0,0 +1,149 @@
+package encryption
+
+import (
+	"crypto/sha256"
+	"encoding/base64"
+	"errors"
+	"fmt"
+	"os"
+	"strings"
+
+	"golang.org/x/crypto/pbkdf2"
+)
+
+type Config struct {
+	Enabled    bool   `yaml:"enabled"`
+	KeySource  string `yaml:"key_source"`
+	KeyEnvVar  string `yaml:"key_env_var"`
+	KeyFile    string `yaml:"key_file"`
+	Key        string `yaml:"key"`
+	Passphrase string `yaml:"passphrase"`
+	Salt       string `yaml:"salt"`
+}
+
+func (cfg Config) Validate() error {
+	if !cfg.Enabled {
+		return nil
+	}
+
+	src := strings.ToLower(strings.TrimSpace(cfg.KeySource))
+	if src == "" {
+		return errors.New("encryption key source is required when encryption is enabled")
+	}
+
+	switch src {
+	case "env":
+		if strings.TrimSpace(cfg.KeyEnvVar) == "" {
+			return errors.New("key_env_var is required for env key source")
+		}
+		if cfg.KeyFile != "" || cfg.Key != "" || cfg.Passphrase != "" || cfg.Salt != "" {
+			return errors.New("mutually exclusive fields set for env key source")
+		}
+	case "file":
+		if strings.TrimSpace(cfg.KeyFile) == "" {
+			return errors.New("key_file is required for file key source")
+		}
+		if cfg.KeyEnvVar != "" || cfg.Key != "" || cfg.Passphrase != "" || cfg.Salt != "" {
+			return errors.New("mutually exclusive fields set for file key source")
+		}
+	case "literal":
+		if strings.TrimSpace(cfg.Key) == "" {
+			return errors.New("key is required for literal key source")
+		}
+		if cfg.KeyEnvVar != "" || cfg.KeyFile != "" || cfg.Passphrase != "" || cfg.Salt != "" {
+			return errors.New("mutually exclusive fields set for literal key source")
+		}
+	case "derive":
+		if strings.TrimSpace(cfg.Passphrase) == "" {
+			return errors.New("passphrase is required for derive key source")
+		}
+		if strings.TrimSpace(cfg.Salt) == "" {
+			return errors.New("salt is required for derive key source")
+		}
+		if cfg.KeyEnvVar != "" || cfg.KeyFile != "" || cfg.Key != "" {
+			return errors.New("mutually exclusive fields set for derive key source")
+		}
+	default:
+		return fmt.Errorf("unsupported encryption key source: %s", cfg.KeySource)
+	}
+
+	return nil
+}
+
+func decodeBase64Key(s string) ([]byte, error) {
+	s = strings.TrimSpace(s)
+	b, err := base64.StdEncoding.DecodeString(s)
+	if err != nil {
+		b, err = base64.RawStdEncoding.DecodeString(s)
+		if err != nil {
+			return nil, err
+		}
+	}
+	return b, nil
+}
+
+func LoadKey(cfg Config) ([]byte, error) {
+	if err := cfg.Validate(); err != nil {
+		return nil, fmt.Errorf("encryption config validation failed: %w", err)
+	}
+
+	src := strings.ToLower(strings.TrimSpace(cfg.KeySource))
+	switch src {
+	case "env":
+		envVar := strings.TrimSpace(cfg.KeyEnvVar)
+		val, ok := os.LookupEnv(envVar)
+		if !ok {
+			return nil, fmt.Errorf("encryption key env var %s is unset", envVar)
+		}
+		b, err := decodeBase64Key(val)
+		if err != nil {
+			return nil, fmt.Errorf("invalid base64 encryption key in env var %s: %w", envVar, err)
+		}
+		if len(b) != 32 {
+			return nil, fmt.Errorf("%w: key from env var %s must be 32 bytes, got %d", ErrInvalidKey, envVar, len(b))
+		}
+		return b, nil
+
+	case "file":
+		filePath := strings.TrimSpace(cfg.KeyFile)
+		data, err := os.ReadFile(filePath)
+		if err != nil {
+			return nil, fmt.Errorf("failed to read encryption key file %s: %w", filePath, err)
+		}
+		b, err := decodeBase64Key(string(data))
+		if err != nil {
+			return nil, fmt.Errorf("invalid base64 encryption key in file %s: %w", filePath, err)
+		}
+		if len(b) != 32 {
+			return nil, fmt.Errorf("%w: key from file %s must be 32 bytes, got %d", ErrInvalidKey, filePath, len(b))
+		}
+		return b, nil
+
+	case "literal":
+		b, err := decodeBase64Key(cfg.Key)
+		if err != nil {
+			return nil, fmt.Errorf("invalid base64 literal encryption key: %w", err)
+		}
+		if len(b) != 32 {
+			return nil, fmt.Errorf("%w: literal encryption key must be 32 bytes, got %d", ErrInvalidKey, len(b))
+		}
+		return b, nil
+
+	case "derive":
+		if strings.TrimSpace(cfg.Passphrase) == "" {
+			return nil, errors.New("empty passphrase rejected for encryption key derivation")
+		}
+		saltBytes, err := decodeBase64Key(cfg.Salt)
+		if err != nil {
+			return nil, fmt.Errorf("invalid base64 encryption salt: %w", err)
+		}
+		if len(saltBytes) < 16 {
+			return nil, fmt.Errorf("encryption salt must be at least 16 bytes, got %d", len(saltBytes))
+		}
+		key := pbkdf2.Key([]byte(cfg.Passphrase), saltBytes, 100000, 32, sha256.New)
+		return key, nil
+
+	default:
+		return nil, fmt.Errorf("unsupported encryption key source: %s", cfg.KeySource)
+	}
+}
diff --git a/encryption/encryption.go b/encryption/encryption.go
new file mode 100644
index 0000000..efe8019
--- /dev/null
+++ b/encryption/encryption.go
@@ -0,0 +1,319 @@
+package encryption
+
+import (
+	"crypto/aes"
+	"crypto/cipher"
+	"crypto/hmac"
+	"crypto/rand"
+	"crypto/sha256"
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"io"
+)
+
+var ErrInvalidKey = errors.New("invalid encryption key")
+
+const (
+	chunkSize = 64 * 1024 // 64KB
+	headerSize = 3
+	nonceSize = 12
+	tagSize = 16
+	hmacSize = 32
+)
+
+var magicHeader = []byte{0x4F, 0x44, 0x01}
+
+type Encryptor struct {
+	key []byte
+}
+
+func NewEncryptor(key []byte) (*Encryptor, error) {
+	if len(key) != 32 {
+		return nil, fmt.Errorf("%w: key must be 32 bytes, got %d", ErrInvalidKey, len(key))
+	}
+	k := make([]byte, 32)
+	copy(k, key)
+	return &Encryptor{key: k}, nil
+}
+
+func (e *Encryptor) EncryptWriter(w io.Writer) io.WriteCloser {
+	block, err := aes.NewCipher(e.key)
+	if err != nil {
+		// Should not happen as key size is validated
+		panic(err)
+	}
+	aead, err := cipher.NewGCM(block)
+	if err != nil {
+		panic(err)
+	}
+
+	return &encryptWriter{
+		w:     w,
+		key:   e.key,
+		aead:  aead,
+		hmac:  hmac.New(sha256.New, e.key),
+		buf:   make([]byte, 0, chunkSize),
+	}
+}
+
+type encryptWriter struct {
+	w             io.Writer
+	key           []byte
+	aead          cipher.AEAD
+	hmac          io.Writer
+	buf           []byte
+	headerWritten bool
+	closed        bool
+	writeErr      error
+}
+
+func (ew *encryptWriter) Write(p []byte) (int, error) {
+	if ew.closed {
+		return 0, io.ErrClosedPipe
+	}
+	if ew.writeErr != nil {
+		return 0, ew.writeErr
+	}
+
+	if !ew.headerWritten {
+		if _, err := ew.w.Write(magicHeader); err != nil {
+			ew.writeErr = err
+			return 0, err
+		}
+		ew.headerWritten = true
+	}
+
+	totalWritten := 0
+	for len(p) > 0 {
+		toCopy := chunkSize - len(ew.buf)
+		if toCopy > len(p) {
+			toCopy = len(p)
+		}
+		ew.buf = append(ew.buf, p[:toCopy]...)
+		p = p[toCopy:]
+		totalWritten += toCopy
+
+		if len(ew.buf) == chunkSize {
+			if err := ew.flushChunk(ew.buf); err != nil {
+				ew.writeErr = err
+				return totalWritten - len(p), err
+			}
+			ew.buf = ew.buf[:0]
+		}
+	}
+
+	return totalWritten, nil
+}
+
+func (ew *encryptWriter) flushChunk(plain []byte) error {
+	nonce := make([]byte, nonceSize)
+	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
+		return fmt.Errorf("failed to generate nonce: %w", err)
+	}
+
+	ciphertextAndTag := ew.aead.Seal(nil, nonce, plain, nil)
+	length := uint32(len(nonce) + len(ciphertextAndTag))
+
+	lenBuf := make([]byte, 4)
+	binary.BigEndian.PutUint32(lenBuf, length)
+
+	// Length prefix
+	if _, err := ew.w.Write(lenBuf); err != nil {
+		return err
+	}
+	if _, err := ew.hmac.Write(lenBuf); err != nil {
+		return err
+	}
+
+	// Nonce
+	if _, err := ew.w.Write(nonce); err != nil {
+		return err
+	}
+	if _, err := ew.hmac.Write(nonce); err != nil {
+		return err
+	}
+
+	// Ciphertext + Tag
+	if _, err := ew.w.Write(ciphertextAndTag); err != nil {
+		return err
+	}
+	if _, err := ew.hmac.Write(ciphertextAndTag); err != nil {
+		return err
+	}
+
+	return nil
+}
+
+func (ew *encryptWriter) Close() error {
+	if ew.closed {
+		return nil
+	}
+	ew.closed = true
+
+	if !ew.headerWritten {
+		if _, err := ew.w.Write(magicHeader); err != nil {
+			return err
+		}
+		ew.headerWritten = true
+	}
+
+	if len(ew.buf) > 0 {
+		if err := ew.flushChunk(ew.buf); err != nil {
+			return err
+		}
+		ew.buf = nil
+	}
+
+	// Zero sentinel: 4 zero bytes
+	sentinel := []byte{0x00, 0x00, 0x00, 0x00}
+	if _, err := ew.w.Write(sentinel); err != nil {
+		return err
+	}
+
+	// HMAC-SHA256 (32 bytes) computed over all bytes between header and sentinel
+	mac := ew.hmac.(interface{ Sum([]byte) []byte }).Sum(nil)
+	if _, err := ew.w.Write(mac); err != nil {
+		return err
+	}
+
+	return nil
+}
+
+func DecryptReader(r io.Reader, key []byte) (io.Reader, error) {
+	k := make([]byte, len(key))
+	copy(k, key)
+	return &decryptReader{
+		r:   r,
+		key: k,
+	}, nil
+}
+
+type decryptReader struct {
+	r          io.Reader
+	key        []byte
+	aead       cipher.AEAD
+	hmac       io.Writer
+	hmacHash   interface{ Sum([]byte) []byte }
+	initDone   bool
+	initErr    error
+	plainBuf   []byte
+	eofReached bool
+}
+
+func (dr *decryptReader) init() error {
+	if dr.initDone {
+		return dr.initErr
+	}
+	dr.initDone = true
+
+	if len(dr.key) != 32 {
+		dr.initErr = fmt.Errorf("%w: key must be 32 bytes, got %d", ErrInvalidKey, len(dr.key))
+		return dr.initErr
+	}
+
+	block, err := aes.NewCipher(dr.key)
+	if err != nil {
+		dr.initErr = err
+		return dr.initErr
+	}
+
+	aead, err := cipher.NewGCM(block)
+	if err != nil {
+		dr.initErr = err
+		return dr.initErr
+	}
+	dr.aead = aead
+
+	h := hmac.New(sha256.New, dr.key)
+	dr.hmac = h
+	dr.hmacHash = h
+
+	header := make([]byte, headerSize)
+	if _, err := io.ReadFull(dr.r, header); err != nil {
+		dr.initErr = fmt.Errorf("truncated data: failed to read header: %w", err)
+		return dr.initErr
+	}
+
+	if header[0] != 0x4F || header[1] != 0x44 {
+		dr.initErr = errors.New("invalid header: wrong magic")
+		return dr.initErr
+	}
+
+	if header[2] != 0x01 {
+		dr.initErr = errors.New("unsupported version: expected 0x01")
+		return dr.initErr
+	}
+
+	return nil
+}
+
+func (dr *decryptReader) Read(p []byte) (int, error) {
+	if err := dr.init(); err != nil {
+		return 0, err
+	}
+
+	for len(dr.plainBuf) == 0 && !dr.eofReached {
+		lenBuf := make([]byte, 4)
+		if _, err := io.ReadFull(dr.r, lenBuf); err != nil {
+			return 0, fmt.Errorf("truncated data: failed to read chunk length: %w", err)
+		}
+
+		chunkLen := binary.BigEndian.Uint32(lenBuf)
+		if chunkLen == 0 {
+			// Zero sentinel reached. Read HMAC (32 bytes)
+			macBuf := make([]byte, hmacSize)
+			if _, err := io.ReadFull(dr.r, macBuf); err != nil {
+				return 0, fmt.Errorf("truncated data: failed to read HMAC: %w", err)
+			}
+
+			computedMAC := dr.hmacHash.Sum(nil)
+			if !hmac.Equal(computedMAC, macBuf) {
+				return 0, errors.New("integrity check failed: HMAC mismatch")
+			}
+
+			dr.eofReached = true
+			break
+		}
+
+		// Read chunk
+		if chunkLen < nonceSize+tagSize {
+			return 0, fmt.Errorf("truncated data: invalid chunk length %d", chunkLen)
+		}
+
+		if _, err := dr.hmac.Write(lenBuf); err != nil {
+			return 0, err
+		}
+
+		chunkBuf := make([]byte, chunkLen)
+		if _, err := io.ReadFull(dr.r, chunkBuf); err != nil {
+			return 0, fmt.Errorf("truncated data: failed to read chunk payload: %w", err)
+		}
+
+		if _, err := dr.hmac.Write(chunkBuf); err != nil {
+			return 0, err
+		}
+
+		nonce := chunkBuf[:nonceSize]
+		ciphertextAndTag := chunkBuf[nonceSize:]
+
+		plaintext, err := dr.aead.Open(nil, nonce, ciphertextAndTag, nil)
+		if err != nil {
+			return 0, fmt.Errorf("integrity check failed: decryption failed (wrong key or corrupted chunk): %w", err)
+		}
+
+		dr.plainBuf = plaintext
+	}
+
+	if len(dr.plainBuf) > 0 {
+		n := copy(p, dr.plainBuf)
+		dr.plainBuf = dr.plainBuf[n:]
+		return n, nil
+	}
+
+	if dr.eofReached {
+		return 0, io.EOF
+	}
+
+	return 0, nil
+}
diff --git a/encryption/encryption_test.go b/encryption/encryption_test.go
new file mode 100644
index 0000000..cbf64fc
--- /dev/null
+++ b/encryption/encryption_test.go
@@ -0,0 +1,266 @@
+package encryption
+
+import (
+	"bytes"
+	"crypto/rand"
+	"encoding/base64"
+	"errors"
+	"io"
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/stretchr/testify/assert"
+	"github.com/stretchr/testify/require"
+)
+
+func generateKey(t *testing.T) []byte {
+	key := make([]byte, 32)
+	_, err := io.ReadFull(rand.Reader, key)
+	require.NoError(t, err)
+	return key
+}
+
+func TestNewEncryptorKeyValidation(t *testing.T) {
+	_, err := NewEncryptor(make([]byte, 16))
+	assert.Error(t, err)
+	assert.True(t, errors.Is(err, ErrInvalidKey))
+
+	_, err = NewEncryptor(make([]byte, 32))
+	assert.NoError(t, err)
+}
+
+func TestEncryptDecryptRoundTrip(t *testing.T) {
+	key := generateKey(t)
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	testCases := []struct {
+		name string
+		data []byte
+	}{
+		{"empty", []byte("")},
+		{"small", []byte("hello world encryption test")},
+		{"exact chunk", make([]byte, 64*1024)},
+		{"multi chunk", make([]byte, 150*1024)},
+	}
+
+	for _, tc := range testCases {
+		t.Run(tc.name, func(t *testing.T) {
+			if len(tc.data) > 0 && tc.name != "small" {
+				_, _ = rand.Read(tc.data)
+			}
+
+			var buf bytes.Buffer
+			ew := enc.EncryptWriter(&buf)
+
+			n, err := ew.Write(tc.data)
+			require.NoError(t, err)
+			assert.Equal(t, len(tc.data), n)
+
+			// Idempotent Close test
+			require.NoError(t, ew.Close())
+			require.NoError(t, ew.Close())
+
+			dr, err := DecryptReader(&buf, key)
+			require.NoError(t, err)
+
+			plain, err := io.ReadAll(dr)
+			require.NoError(t, err)
+			assert.Equal(t, tc.data, plain)
+		})
+	}
+}
+
+func TestEncryptionsDiffer(t *testing.T) {
+	key := generateKey(t)
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	plaintext := []byte("identical plaintext data")
+
+	var buf1, buf2 bytes.Buffer
+
+	w1 := enc.EncryptWriter(&buf1)
+	_, _ = w1.Write(plaintext)
+	_ = w1.Close()
+
+	w2 := enc.EncryptWriter(&buf2)
+	_, _ = w2.Write(plaintext)
+	_ = w2.Close()
+
+	assert.NotEqual(t, buf1.Bytes(), buf2.Bytes())
+}
+
+func TestInvalidHeaderAndVersion(t *testing.T) {
+	key := generateKey(t)
+
+	// Wrong magic
+	badMagicData := []byte{0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00}
+	dr, err := DecryptReader(bytes.NewReader(badMagicData), key)
+	require.NoError(t, err)
+	_, err = io.ReadAll(dr)
+	assert.Error(t, err)
+	assert.Contains(t, err.Error(), "invalid header")
+
+	// Unsupported version
+	badVersionData := []byte{0x4F, 0x44, 0x02, 0x00, 0x00, 0x00, 0x00}
+	dr, err = DecryptReader(bytes.NewReader(badVersionData), key)
+	require.NoError(t, err)
+	_, err = io.ReadAll(dr)
+	assert.Error(t, err)
+	assert.Contains(t, err.Error(), "unsupported version")
+}
+
+func TestHMACIntegrityFailure(t *testing.T) {
+	key := generateKey(t)
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	var buf bytes.Buffer
+	ew := enc.EncryptWriter(&buf)
+	_, _ = ew.Write([]byte("some data to tamper"))
+	_ = ew.Close()
+
+	encryptedData := buf.Bytes()
+	// Tamper a byte in the encrypted chunk
+	encryptedData[len(encryptedData)-40] ^= 0xFF
+
+	dr, err := DecryptReader(bytes.NewReader(encryptedData), key)
+	require.NoError(t, err)
+	_, err = io.ReadAll(dr)
+	assert.Error(t, err)
+	assert.Contains(t, err.Error(), "integrity")
+
+	// Tamper HMAC at the end
+	var buf2 bytes.Buffer
+	ew2 := enc.EncryptWriter(&buf2)
+	_, _ = ew2.Write([]byte("some data to tamper hmac"))
+	_ = ew2.Close()
+
+	data2 := buf2.Bytes()
+	data2[len(data2)-1] ^= 0xFF // tamper last byte of HMAC
